        /*
         *  Google Analytics
         */

        function simcore_ga ( category, action, label )
        {
            if (get_cfg('use_ga') == false) {
                return ;
            }

            if (typeof gtag !== "undefined")
            {
                gtag('event',
                     label,
                     {
                        'event_category': category,
                        'event_action':   action,
                        'event_label':    label
                     });
            }
        }

