						   var o_ref      = sim_p.states[rf_name][reg_w_obj.value] ;

						   var o_verbal = o_ref.name ;
						   if (typeof o_ref.verbal != "undefined") {
						       o_verbal = o_ref.verbal ;
                                                   }

                                                   var verbose = get_cfg('verbal_verbose') ;
